"""Source-reviewed, bounded workflows for designers and document owners."""
from html import escape as e
import hashlib

DATE = '2026-11-22'
ROOT = 'https://github.com/anthropics/skills'


def command(text):
    target = 'playbook-' + hashlib.sha256(text.encode()).hexdigest()[:12]
    if text.startswith('/plugin'):
        return ''.join(command(line) for line in text.splitlines()) if '\n' in text else '<button type="button" class="copy-button" data-copy-target="'+target+'">Copy command</button><pre class="code-block"><code id="'+target+'">'+e(text)+'</code></pre>'
    label = 'Copy command' if text.startswith('claude plugin') else 'Copy starter brief'
    return '<button type="button" class="copy-button" data-copy-target="'+target+'">'+label+'</button><pre class="code-block"><code id="'+target+'">'+e(text)+'</code></pre>'


def sources(items):
    return '<details><summary>Sources and review coverage</summary><p>Reviewed '+DATE+'. First-party documentation was read for these instructions. SkillLantern did not install these plugins, connect a Figma account, or reproduce the deliverables. The checks above are for your own first attempt.</p><ul>'+''.join('<li><a href="'+e(url, quote=True)+'">'+e(label)+'</a></li>' for label,url in items)+'</ul></details>'


def add_practical_playbooks(pages):
    css = '<style>.playbook-tools{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:1rem;margin:1.5rem 0}.playbook-tool{padding:1rem;border:1px solid var(--line);border-radius:12px;background:var(--surface,#fff)}.playbook-tool b{display:inline-grid;place-items:center;width:40px;height:40px;margin-right:.6rem;background:#e6eddb;border-radius:10px;color:#294638}.playbook-tool p{margin-bottom:0}.playbook-article{max-width:850px}.playbook-article .code-block{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;max-width:100%;box-sizing:border-box}.playbook-article table{display:block;overflow-x:auto;max-width:100%}.playbook-article section{margin:2rem 0}.playbook-article details{margin-top:2rem;padding:1rem;border:1px solid var(--line);border-radius:10px}.playbook-article summary{cursor:pointer;font-weight:650}.playbook-article button:focus-visible{outline:3px solid #829c60;outline-offset:3px}</style>'
    common = css+'<p><a href="../guides.html">All guides</a> · <a href="../collections.html">Skills by task</a></p>'
    design = common + '''<header class="page-intro"><p class="eyebrow">Design workflow · Source reviewed 2026-11-22</p><h1>A distinctive design, grounded in your Figma file.</h1><p class="lede">Combine Anthropic’s Frontend Design skill with Figma’s official plugin: a direction for the visual work, and a connection to the design you actually own.</p></header><article class="prose playbook-article">
<section><h2>Your toolkit</h2><div class="playbook-tools"><a class="playbook-tool" href="../capabilities/frontend-design.html"><b aria-hidden="true">Aa</b><strong>Frontend Design</strong><p>Choose a visual direction. View and save skill.</p></a><a class="playbook-tool" href="../capabilities/figma-official.html"><b aria-hidden="true">Fg</b><strong>Official Figma</strong><p>Connect the source design. View and save plugin.</p></a></div><h2>Choose your starting point</h2><p>Start with Frontend Design when your brief leaves room to explore. Add Figma when you have an approved frame to implement.</p><p>A skill supplies instructions. A plugin bundles capabilities; Figma’s includes an MCP connection and its own skills. MCP gives the agent access to tools and data. Neither automatically makes an interface usable.</p></section>
<section><h2>Before you start</h2><p>This route uses Claude Code, a local website project and an account with Claude Code access. If you are new to terminals, follow the <a href="https://code.claude.com/docs/en/quickstart">official quickstart</a> first. You also need a Figma account with access to the target file. The remote connection does not require Figma’s desktop app.</p><p>Claude Code needs eligible paid or API access. Figma read limits depend on plan and seat: Starter, View and Collab access currently allow up to 20 reads per month. Check the linked limits before a large task; some image-generation actions consume separate credits.</p></section>
<section><h2>1. Add design guidance</h2><p>Inside a Claude Code conversation in a copy of your website project, run:</p>'''+command('/plugin marketplace add anthropics/skills\n/plugin install example-skills@anthropic-agent-skills')+'''<p>This installs the example collection, which includes Frontend Design. Confirm it in the plugin manager, then request the skill by name.</p></section>
<section><h2>2. Connect the official Figma plugin</h2><p>In your terminal, run the command from Figma’s setup page:</p>'''+command('claude plugin install figma@claude-plugins-official')+'''<p>Restart Claude Code. Open <code>/plugin</code>, go to Installed, select Figma, and follow the browser sign-in. Review access before allowing it. Return to the plugin manager and confirm connected status. If your organisation blocks it, follow its policy and Figma’s manual setup instructions.</p></section>
<section><h2>3. Give the design a real subject</h2><p>Paste your own frame link into this starter brief.</p>'''+command('Use Frontend Design and the official Figma tools.\nSubject: a local ceramics studio offering one beginner workshop.\nAudience: adults choosing their first hands-on class.\nPrimary action: view available workshop dates.\nUse this approved Figma frame: [paste the frame link].\nFirst inspect the frame and identify the existing typography, spacing and components.\nPropose one visual direction grounded in clay, tools and the workshop setting.\nExplain any departure from the approved frame before implementing it.\nBuild only the workshop page in this project. Keep dates and prices as supplied; mark missing facts.\nCheck mobile layout, keyboard focus and reduced motion. Do not publish.')+'''<p>If you have no approved frame, skip the Figma connection and start from the brief. If you have a strict design system, ask the agent to preserve it; expressive guidance must not override your approved constraints.</p></section>
<section><h2>4. Review before keeping it</h2><ul><li>Ask which frame and components were read. A connection badge alone does not prove the correct file was used.</li><li>Compare the rendered page with the chosen frame at desktop and narrow mobile widths.</li><li>Reach the primary action using only the keyboard; inspect visible focus and meaningful button text.</li><li>Check real dates, prices, image rights and font availability yourself.</li></ul><p>If access fails, check the signed-in account, frame URL and file permissions. If the result drifts, reduce the task to one frame and list the elements that must match. Disable the plugin in the manager when you no longer need it; disconnect account access through the provider when appropriate. Keep your project copy until you approve the diff.</p></section>'''+sources([('Anthropic skills: installation and account routes', ROOT),('Plugin manifest: which skills each collection contains', ROOT+'/blob/main/.claude-plugin/marketplace.json'),('Frontend Design instructions',ROOT+'/blob/main/skills/frontend-design/SKILL.md'),('Figma official remote setup','https://developers.figma.com/docs/figma-mcp-server/remote-server-installation/'),('Figma rate limits and access','https://developers.figma.com/docs/figma-mcp-server/rate-limits-access/'),('Claude Code setup and authentication','https://code.claude.com/docs/en/setup')])+'''</article>'''
    report = common + '''<header class="page-intro"><p class="eyebrow">Writing and operations · Source reviewed 2026-11-22</p><h1>Turn scattered notes into a Word report people can use.</h1><p class="lede">A complete handoff for consultants, course organisers and operations teams: establish the facts, shape the explanation, then produce an editable document.</p></header><article class="prose playbook-article">
<section><h2>Your toolkit</h2><div class="playbook-tools"><a class="playbook-tool" href="../capabilities/doc-coauthoring.html"><b aria-hidden="true">Co</b><strong>Doc Coauthoring</strong><p>Develop the argument. View and save skill.</p></a><a class="playbook-tool" href="../capabilities/docx.html"><b aria-hidden="true">W</b><strong>DOCX</strong><p>Produce the Word file. View and save skill.</p></a></div><h2>Choose this for a substantial handoff</h2><p>Doc Coauthoring helps transfer context, refine a structure and challenge the draft with reader questions. DOCX handles the Word deliverable. Choose this combination for a workshop retrospective, an internal proposal or an operating guide. For a short email, a normal prompt is usually enough.</p><p>This is a source-based editorial pick for structured writing, not a benchmark winner. It cannot validate missing facts or supply your organisation’s approval.</p></section>
<section><h2>Choose your app before installing</h2><p><strong>Beginner route:</strong> use a paid Claude.ai plan with file creation and the relevant skills enabled for your account. Anthropic’s repository describes its example skills as available on paid plans. Start with the document tools enabled for your account; this route needs no terminal.</p><p><strong>Local route:</strong> use Claude Code with file access and eligible paid or API access. The commands below install both the example collection and document collection. A plugin is a package; Doc Coauthoring and DOCX are individual skills inside those packages.</p>'''+command('/plugin marketplace add anthropics/skills\n/plugin install example-skills@anthropic-agent-skills\n/plugin install document-skills@anthropic-agent-skills')+'''<p>Confirm both collections in <code>/plugin</code>. Local Word production also needs the runtime tools the DOCX skill uses: Node’s <code>docx</code> package, and tools such as Pandoc, LibreOffice and Poppler for reading or rendering. The hosted environment’s preinstalled tools are not guaranteed on your computer. Ask the agent to check availability before generating; follow upstream setup rather than assuming installation succeeded.</p></section>
<section><h2>1. Build a small source pack</h2><p>Create a copy of approved notes and a short facts file. Include audience, purpose, required headings, source dates, the reporting period and unresolved questions. Use a practice example with invented data labelled as synthetic. Keep customer details and confidential attachments out of the exercise.</p><p>For a workshop retrospective, supply actual attendance, feedback you are allowed to use, observed problems and the decisions already made. Missing feedback stays unknown.</p></section>
<section><h2>2. Agree the content before formatting</h2>'''+command('Use Doc Coauthoring to prepare a two-page workshop retrospective for an operations lead.\nRead only the source files I supplied. First list confirmed facts, proposals and missing information.\nAsk for the decisions needed before drafting.\nPropose a structure covering outcomes, observations, actions, owners and unresolved questions.\nKeep evidence dates and source references visible. Do not invent participant quotes or outcomes.\nAfter we approve the draft, give me five questions a new reader should be able to answer.')+'''<p>Review the draft section by section. Then open a fresh conversation with only the draft and the five questions. Check whether the answers are supported by the document. Then check the draft with an intended reader.</p></section>
<section><h2>3. Produce an editable Word handoff</h2>'''+command('Use DOCX to turn the approved draft into workshop-retrospective.docx.\nUse semantic heading styles, page numbers, a readable action table and descriptive links.\nKeep source references and unresolved questions. Preserve the original notes.\nReturn the editable Word file and a rendering or preview if available.\nTell me which checks actually ran and which could not run. Do not send or publish it.')+'''<p>Expected output: a downloadable <code>.docx</code> with editable content. Download and open it in your intended Word-compatible app.</p></section>
<section><h2>4. Accept it only after these checks</h2><ul><li>Compare names, dates, counts and quoted statements against the source pack.</li><li>Use the document navigation pane to check the heading hierarchy.</li><li>Inspect every page for split tables, clipped text and unwanted blank pages.</li><li>Confirm each action has an owner or an explicit unassigned status; proposals must remain proposals.</li><li>Open and edit the file in the app your recipient will use. </li></ul><p>If local rendering is unavailable, mark visual validation incomplete and inspect manually. If the file will not open, retain the approved plain-text draft and ask the agent to diagnose the export. Disable unneeded plugin collections through the plugin manager. Keep original files and a clearly named revision so you can discard the generated copy.</p></section>'''+sources([('Anthropic skills: Claude.ai availability and Claude Code installation',ROOT),('Plugin manifest: Doc Coauthoring and DOCX collection membership',ROOT+'/blob/main/.claude-plugin/marketplace.json'),('Doc Coauthoring stages and reader review',ROOT+'/blob/main/skills/doc-coauthoring/SKILL.md'),('DOCX capabilities, dependencies and output validation',ROOT+'/blob/main/skills/docx/SKILL.md'),('Claude Code setup and account access','https://code.claude.com/docs/en/setup')])+'''</article>'''
    specs = [('guides/distinctive-design-figma.html','Frontend Design and Figma: a practical setup','Connect the official Figma plugin and Anthropic Frontend Design skill for a brief-led website workflow.',design),('guides/notes-to-word-report.html','From notes to a Word report with Claude skills','Use Doc Coauthoring and DOCX for a source-based report, from context gathering to an editable Word handoff.',report)]
    for path,title,description,body in specs:
        pages[path] = dict(path=path,title=title,description=description,body=body,activeNav='guides',observedOn=DATE)
    index = pages.get('guides.html')
    if index:
        cards=''.join('<a class="guide-list-card" href="'+path+'"><span class="cap-kind">Practical setup</span><h2>'+e(title)+'</h2><p>'+e(description)+'</p><span>Read guide</span></a>' for path,title,description,body in specs)
        marker = '<div class="guide-list">'
        if marker not in index['body']: raise ValueError('Guide list missing')
        index['body'] = index['body'].replace(marker,marker+cards,1)
